<?php
if(!defined('ABSPATH')){exit(1);}global$wpdb;$f=get_option('cvt_closeout_fixture');$id=absint($f['order_id']);$order=wc_get_order($id);$assert=static function($ok,$message){if(!$ok){throw new RuntimeException($message);}};$events=$wpdb->prefix.'cvd_order_events';$ledger=$wpdb->prefix.'cvd_messenger_ledger';
$assert('closed'===CVD_Delivery::status($order),'delivery no quedó closed');$assert('verified'===$order->get_meta('_cvd_cash_status',true),'payment no quedó verified');$assert('delivered'===$order->get_meta('_cvd_operation_status',true),'operation no quedó delivered');$assert('completed'===$order->get_status(),'WooCommerce no quedó completed');$assert('approved'===$order->get_meta('_cvd_commission_status',true),'comisión no quedó approved');$assert('approved'===$order->get_meta('_cvd_messenger_earning_status',true),'earning no quedó approved');$assert('available'===$order->get_meta('_cvd_messenger_ledger_status',true),'ledger meta incorrecto');foreach(array('_cvd_cash_returned_at','_cvd_cash_verified_at')as$key){$assert((bool)$order->get_meta($key,true),'falta timestamp '.$key);}
foreach(array('delivery:cash_returned','payment:returned','delivery:closed','payment:verified','operation:delivered','commission:approved','order:completed')as$pair){list($domain,$to)=explode(':',$pair);$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$events} WHERE order_id=%d AND domain=%s AND to_state=%s",$id,$domain,$to));$assert(1===$count,'evento no exactly-once '.$pair);}
$assert(1===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$ledger} WHERE order_id=%d AND entry_type='earning' AND status='available'",$id)),'ledger no exactly-once');$history=(array)$order->get_meta('_cvd_delivery_history',true);foreach(array('cash_returned','closed')as$to){$assert(1===count(array_filter($history,static fn($e)=>$to===$e['to'])),'historial duplicado '.$to);}$commission_history=(array)$order->get_meta('_cvd_commission_history',true);$assert(1===count(array_filter($commission_history,static fn($e)=>'approved'===$e['to'])),'comisión aprobada más de una vez');$receipts=(array)$order->get_meta('_cvd_transition_receipts',true);foreach(array('closeout:'.$id.':cash_returned','closeout:'.$id.':closed')as$key){$assert(isset($receipts[hash('sha256',$key)]),'falta receipt '.$key);}
wp_set_current_user(absint($f['admin_id']));$assert(CVD_Delivery::close_after_cash_received($order),'retry tras timeout no fue replay seguro');$assert(1===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$ledger} WHERE order_id=%d AND entry_type='earning'",$id)),'retry duplicó ledger');echo "OK: cierre 1C.3 verificado directamente en MariaDB.\n";
